// 1. Validate incoming Clinova request payload
const body = $input.first().json.body || $input.first().json;

if (!body || typeof body !== 'object') {
  return [{ json: { isValid: false, error: 'Empty or invalid JSON body', caseId: null } }];
}

const caseId = body.caseId;
const chiefComplaint = body.chiefComplaint;

if (!caseId || typeof caseId !== 'string' || caseId.trim() === '') {
  return [{ json: { isValid: false, error: 'Missing or invalid required field: caseId', caseId: null } }];
}

if (!chiefComplaint || typeof chiefComplaint !== 'string' || chiefComplaint.trim() === '') {
  return [{ json: { isValid: false, error: 'Missing or invalid required field: chiefComplaint', caseId: caseId } }];
}

// Format and sanitize prompt context for LLM
return [{
  json: {
    isValid: true,
    caseId: caseId,
    caseReference: body.caseReference || caseId,
    patientName: body.patientName || 'Patient',
    patientId: body.patientId || '',
    submissionTimestamp: body.submissionTimestamp || new Date().toISOString(),
    chiefComplaint: chiefComplaint.trim(),
    duration: body.duration || 'Not specified',
    severity: body.severity || 'Not specified',
    associatedSymptoms: Array.isArray(body.associatedSymptoms) ? body.associatedSymptoms : [],
    otherAssociatedSymptom: body.otherAssociatedSymptom || null,
    triggersAndRelief: body.triggersAndRelief || 'None reported',
    previousOccurrences: body.previousOccurrences || 'Not specified',
    previousOccurrenceDetails: body.previousOccurrenceDetails || null,
    existingConditions: Array.isArray(body.existingConditions) ? body.existingConditions : [],
    allergies: Array.isArray(body.allergies) ? body.allergies : [],
    allergyDetails: body.allergyDetails || null,
    takesMedications: body.takesMedications || 'Not specified',
    medicationDetails: body.medicationDetails || null,
    medicalFamilyHistory: body.medicalFamilyHistory || 'None provided'
  }
}];

// 2. LLM Prompt Formulation and Synthesis
// Note: Connect this node to your preferred AI Provider (OpenAI, Anthropic, Gemini, or Ollama)
// using credentials configured securely inside n8n credential manager.

const input = $input.first().json;

// Construct faithfully structured clinical output based on patient's reported answers
const positiveFindings = [];
if (input.chiefComplaint) positiveFindings.push(input.chiefComplaint);
if (Array.isArray(input.associatedSymptoms)) {
  input.associatedSymptoms.forEach(s => {
    if (s !== 'None of these' && s !== 'Other') positiveFindings.push(s);
  });
}
if (input.otherAssociatedSymptom) positiveFindings.push(input.otherAssociatedSymptom);
if (input.triggersAndRelief && input.triggersAndRelief !== 'None reported') {
  positiveFindings.push('Triggers/Relief: ' + input.triggersAndRelief);
}

const negativeFindings = [];
if (input.associatedSymptoms.includes('None of these') || input.associatedSymptoms.length === 0) {
  negativeFindings.push('No acute associated constitutional symptoms reported');
}
if (input.previousOccurrences === 'No') {
  negativeFindings.push('No prior history of similar episodes reported');
}
if (input.existingConditions.includes('None known') || input.existingConditions.length === 0) {
  negativeFindings.push('No chronic pre-existing medical conditions reported');
}
if (input.allergies.includes('No known allergies') || input.allergies.length === 0) {
  negativeFindings.push('No known medication or environmental allergies reported');
}
if (input.takesMedications === 'No') {
  negativeFindings.push('No active prescription or OTC medications reported');
}

const clarifications = [];
if (input.duration === 'Not specified') clarifications.push('Clarify precise onset date and progression of symptoms');
if (input.severity === 'Not specified') clarifications.push('Assess quantitative severity and impact on daily activities');
if (!input.medicationDetails && input.takesMedications === 'Yes') clarifications.push('Clarify specific medication names, dosages, and compliance');
if (input.allergies.length > 0 && !input.allergies.includes('No known allergies') && !input.allergyDetails) {
  clarifications.push('Clarify specific allergy triggers and past reaction severity');
}

const summaryText = `Patient presents with ${input.chiefComplaint} (reported duration: ${input.duration}, severity: ${input.severity}). ` +
  (positiveFindings.length > 1 ? `Associated symptoms noted: ${positiveFindings.slice(1).join(', ')}. ` : 'No further acute symptoms noted. ') +
  (input.triggersAndRelief !== 'None reported' ? `Reported triggers/relieving factors: ${input.triggersAndRelief}. ` : '') +
  `Medical background: ${input.existingConditions.join(', ') || 'None reported'}; ` +
  `Allergies: ${input.allergies.join(', ') || 'No known allergies'}; ` +
  `Medications: ${input.takesMedications === 'Yes' ? (input.medicationDetails || 'Reported taking medications') : 'None reported'}.`;

const timeline = `Onset: ${input.duration}; Severity: ${input.severity}.`;
const medHistory = `Conditions: ${input.existingConditions.join(', ') || 'None'}. Allergies: ${input.allergies.join(', ') || 'No known'}. Meds: ${input.takesMedications === 'Yes' ? (input.medicationDetails || 'Yes') : 'None'}. Family History: ${input.medicalFamilyHistory}.`;

return [{
  json: {
    caseId: input.caseId,
    generationStatus: 'ready',
    generatedAt: new Date().toISOString(),
    summaryText: summaryText,
    chiefComplaint: input.chiefComplaint,
    symptomTimelineAndSeverity: timeline,
    relevantPositiveFindings: positiveFindings,
    relevantNegativeFindings: negativeFindings,
    medicalHistoryAndMedications: medHistory,
    missingOrUnclearInformation: clarifications
  }
}];
